 static void clear(ClientSession pc,GameHub hub,boolean world)throws Exception{((BattleTimedStatus)get(pc,"timedStatus")).clear();((BattleAbilityStatus)get(pc,"abilityStatus")).clear();((BattleDragonSkinStatus)get(pc,"dragonSkinStatus")).clear();((BattleCookingStatus)get(pc,"cookingStatus")).clear();((BattleCounterMirrorStatus)get(pc,"counterMirrorStatus")).cancel();if(world)hub.cancelClassicWorldPatience(4,-1,pc.playerObjectId());else hub.cancelPatience((long)get(pc,"currentRoomId"),pc.playerObjectId());}
 static void gear(ClientSession pc,int value,int mr,int armor)throws Exception{set(pc,"sourceEquipmentMagicStats",copy(SourceEquipmentMagicStats.none(),Map.of("itemMagicDamage",value,"itemMagicResistance",mr,"armorTemplateDamageReduction",armor)));}
 static int send(ClientSession caster,ClientSession target,int skill,int mp)throws Exception{ready(caster,mp);set(target,"playerHp",5000);set(target,"playerMaxHp",5000);set(target,"playerMp",1000);set(target,"playerMaxMp",1000);set(caster,"lastCombatTargetObjectId",target.playerObjectId());var p=new Protocol.Writer().c(0x14).c((skill-1)/8).c((skill-1)%8);var area=BattleSpellCatalog.areaAttackSpell(skill);var freeze=BattleSpellCatalog.freezeAttackSpell(skill);boolean selector=skill==72||area!=null&&(area.maximumRange()==0||area.requestShape()==BattleSpellCatalog.RequestShape.SELECTOR_ONLY)||freeze!=null&&(freeze.areaRadius()>0||freeze.lineTargeted());if(skill>=175)selector=false;if(!selector)p.d(target.playerObjectId()).h((int)get(target,"positionX")).h((int)get(target,"positionY"));call(caster,"handle",new Class[]{byte[].class},p.bytes());return 5000-(int)get(target,"playerHp");}
 static int expected(int raw,double factor,int mr,boolean crit){int scaled=(int)(raw*factor);if(crit)scaled*=2;return Math.max(0,(int)(Math.max(0,scaled)*(mr==80?.64:1)));}
 public static void main(String[] args)throws Exception{
  var config=ServerConfig.load(Path.of(args[0]),"standard");ResourceDatabase.load(config);var rf=CombatRegression.current(CombatRules.class);var rules=(CombatRules.Snapshot)rf.get(null);var df=CombatRegression.current(CombatDatabase.class);var data=(CombatDatabase.Snapshot)df.get(null);var ids=Set.of(4,17,25,53,50,80,194,77,87,108,203,207,208,213,60,72,134,181,211);var skills=new HashMap<>(data.skills());for(int id:ids)if(id!=60&&id!=134&&id!=181&&id!=211){var v=skills.get(id);skills.put(id,new CombatDatabase.Skill(id==108?1:17,v.hp(),0,7,0,1,0,0,0,v.probabilityDice(),v.probabilityValue()));}df.set(null,data.withSkills(skills));var ones=new HashMap<String,Double>();String[] names={"Crown","Knight","Elf","Wizard","Darkelf","DragonKnight","Illusionist"};for(var n:names)ones.put("Other_ADD_is"+n+"_MagicPC",1.0);var base=ClassDamageRegression.with(rules,ones);
  var root=Path.of(args[1]);Files.createDirectories(root);var state=new GameStateStore(root.resolve("unused"),false,true);var accounts=new MemoryAccountRepository("fixture","fixture","",0,1,40,52);
  try(var capture=new CaptureLog(root.resolve("capture"));var hub=new GameHub(config,state,accounts);var f=new SourceLoginRegression.Fixture(config,accounts,state,capture,hub,0,ClientSession.Endpoint.GAME);var p=new SourceLoginRegression.Fixture(config,accounts,state,capture,hub,0,ClientSession.Endpoint.GAME);var m=new SourceLoginRegression.Fixture(config,accounts,state,capture,hub,0,ClientSession.Endpoint.GAME);var o=new SourceLoginRegression.Fixture(config,accounts,state,capture,hub,0,ClientSession.Endpoint.GAME)){
   var clock=(java.util.concurrent.ScheduledExecutorService)get(hub,"battleClock");clock.shutdownNow();check(clock.awaitTermination(1,java.util.concurrent.TimeUnit.SECONDS),"clock stopped");var fixtures=List.of(f,p,m,o);for(int i=0;i<4;i++){var pc=fixtures.get(i).session;NativeDirectoryRegression.init(fixtures.get(i),"PlayerMagic"+i,0,config.classicServerNames().get(0));var c=((List<CharacterSummary>)get(pc,"characters")).get(0);set(pc,"characters",List.of(copy(c,Map.of("objectId",0x38660001L+i,"intelligence",9,"originalIntelligence",9,"wisdom",9,"originalWisdom",9))));set(pc,"sourceBaseMagicResistance",new SourceBaseMagicResistance(0,0,0,0,0));set(pc,"sourcePhysicalGrowthStats",SourcePhysicalGrowthStats.classic381());set(pc,"sourceEquipmentMagicStats",SourceEquipmentMagicStats.none());set(pc,"learnedSkills",ids);set(pc,"inventory",RuntimeInventory.fromCatalogCounts(Map.of(40318L,10,40319L,10,40321L,10)));ready(pc,1000);}
   FlowRegression.setup(hub,f.session,p.session,m.session,o.session);var caster=f.session;var target=p.session;set(m.session,"observer",true);set(o.session,"observer",true);
   for(boolean world:new boolean[]{false,true}){
    for(int i=0;i<2;i++){var pc=fixtures.get(i).session;set(pc,"positionX",world?33089+i:32740+i);set(pc,"positionY",world?32717:32798);if(world){set(pc,"phase",Enum.valueOf((Class)get(pc,"phase").getClass(),"WORLD"));set(pc,"classicWorldMapId",4);set(pc,"classicWorldInstanceId",-1);hub.enterClassicWorld(pc,4,33089+i,32717,0);}}
    clear(target,hub,world);gear(target,0,80,5);
    for(int type=0;type<7;type++){CounterDetectionRegression.type(caster,type);for(int value:new int[]{37,-37})for(double factor:new double[]{1,-1,.4,-.4,2.75,-2.75}){gear(caster,value,0,0);rf.set(null,ClassDamageRegression.with(base,Map.of("Other_ADD_is"+names[type]+"_MagicPC",factor)));int actual=send(caster,target,4,1000);check(actual==expected(value-5,factor,80,false),"native signed PC armor before class and MR world="+world+" class="+type+" raw="+(value-5)+" factor="+factor+" actual="+actual);}}
    CounterDetectionRegression.type(caster,3);gear(caster,-37,0,0);rf.set(null,ClassDamageRegression.with(base,Map.of("Other_ADD_isWizard_MagicPC",-1.0,"DISINTEGRATE_CRITICAL_RND",100.0)));
    for(int id:new int[]{17,25,53,50,80,194,77,203,207,208,213,108,72}){clear(target,hub,world);if(id==72){ready(target,1000);CounterDetectionRegression.send(target,60);check((boolean)get(target,"invisible"),"native hide for72");}int mp=id==108?1:1000;int want=expected(id==108?-4:-42,-1,80,id==77)*(id==207?4:1);int actual=send(caster,target,id,mp);check(actual==want,"native signed family="+id+" world="+world+" actual="+actual+" want="+want);if(id==108)check((int)get(caster,"playerHp")==1&&(int)get(caster,"playerMp")==0,"signed Final Burn retains native resource commit");}
    CounterDetectionRegression.type(caster,1);casterType(caster,1);gear(caster,-37,0,0);clear(target,hub,world);rf.set(null,ClassDamageRegression.with(base,Map.of("Other_ADD_isKnight_MagicPC",-1.0)));check(send(caster,target,87,1000)==26,"native Shock Stun signed scalar path");
    CounterDetectionRegression.type(caster,3);gear(caster,37,0,0);rf.set(null,base);
    // Native 181 and211 activation producers; source SKD3 uses -10 and -15 even for magic.
    for(int mask=1;mask<=3;mask++){clear(target,hub,world);ready(target,1000);if((mask&1)!=0){CounterDetectionRegression.send(target,181);check(((BattleDragonSkinStatus)get(target,"dragonSkinStatus")).snapshot(System.nanoTime()).active(),"native Dragon Skin producer");}if((mask&2)!=0){ready(target,1000);call(target,"handle",new Class[]{byte[].class},new Protocol.Writer().c(0x14).c(26).c(2).d(target.playerObjectId()).h((int)get(target,"positionX")).h((int)get(target,"positionY")).bytes());check((int)call(target,"effectivePatiencePhysicalReduction",new Class[]{long.class},System.nanoTime())!=0,"native Patience producer");}int raw=32-((mask&1)!=0?10:0)-((mask&2)!=0?15:0);check(send(caster,target,4,1000)==expected(raw,1,80,false),"source magic SKD3 buff mask="+mask+" world="+world);}
    // The preceding mask3 keeps both source reductions active for a real native mirror cast.
    CounterDetectionRegression.wisdom(target,255);ready(target,1000);CounterDetectionRegression.send(target,134);check(((BattleCounterMirrorStatus)get(target,"counterMirrorStatus")).active(System.nanoTime()),"native mirror producer with SKD3 buffs");check(send(caster,target,4,1000)==0&&5000-(int)get(caster,"playerHp")==7,"source Dragon Skin+Patience reduce before native mirror, class and MR");check(!((BattleCounterMirrorStatus)get(target,"counterMirrorStatus")).active(System.nanoTime()),"positive reduced mirror consumed once");CounterDetectionRegression.wisdom(target,9);
    clear(target,hub,world);gear(caster,1,0,0);gear(target,0,0,5);BattleCookingCatalog.Recipe cooking=null;for(int id=40000;id<60000;id++){var recipe=BattleCookingCatalog.find(id);if(recipe!=null&&recipe.damageReduction()==5&&recipe.magicResistance()==0&&recipe.allElementResistance()==0){cooking=recipe;break;}}check(cooking!=null&&cooking.damageReduction()==5,"source cooking reduction fixture");((BattleCookingStatus)get(target,"cookingStatus")).activate(System.nanoTime(),cooking,60);((BattleAbilityStatus)get(target,"abilityStatus")).activateReductionArmor(System.nanoTime(),60);((BattleAbilityStatus)get(target,"abilityStatus")).activateImmuneToHarm(System.nanoTime(),60,2);rf.set(null,ClassDamageRegression.with(base,Map.of("Other_ADD_isWizard_MagicPC",-1.0)));int level=target.battleLevel();int raw=1-5-5-((Math.max(50,level)-50)/5+1);check(send(caster,target,4,1000)==-(raw>>1),"signed cooking and Reduction Armor before arithmetic shift halves negative odd value world="+world);
    clear(target,hub,world);gear(target,0,80,5);gear(caster,-37,0,0);for(int protection=0;protection<3;protection++){clear(target,hub,world);var status=(BattleTimedStatus)get(target,"timedStatus");long now=System.nanoTime();if(protection==0)status.activateFreeze(now,60);if(protection==1)status.activateEarthBind(now,60);if(protection==2)status.activateAbsoluteBarrier(now,60);int actual=send(caster,target,4,1000);check(actual==0,"protected negative scalar cannot become damage under negative class factor protection="+protection);}
    clear(target,hub,world);gear(caster,-37,0,0);var proc=new SourceMagicDollPower(1,"fixture","ACTIVE_SKILL",0,100,0,0,0,0,0,0,0,25,0,0,0);check((int)call(caster,"nativeMagicDollTriggeredSkillDamage",new Class[]{SourceMagicDollPower.class,ClientSession.class,SourceNpcPhysicalStats.class},proc,target,null)==26,"existing native doll calculation shares signed player reduction and class core; calculation boundary only");
    ready(caster,0);set(target,"playerHp",5000);call(caster,"handle",new Class[]{byte[].class},new Protocol.Writer().c(0x14).c(0).c(3).d(target.playerObjectId()).h((int)get(target,"positionX")).h((int)get(target,"positionY")).bytes());check((int)get(target,"playerHp")==5000&&(int)get(caster,"playerMp")==0,"native resource rejection before signed damage commit");
    clear(target,hub,world);gear(caster,37,0,0);gear(target,0,80,5);rf.set(null,base);
   }
  }finally{rf.set(null,rules);df.set(null,data);}
  System.out.println("PASS player magic signed checks="+checks+"; native seven supplied caster classes/BATTLE/WORLD, signed armor/gear -> cooking/Reduction Armor/SKD3 Dragon Skin10/Patience15 -> arithmetic immune shift -> class int -> critical -> MR; ordinary/freeze/line/area/72/Shock/Final Burn and native buff producers; source learning/nonpositive mirror/reflection healing/high-MR signed commits and other source effects remain pending; no SQL writes/deployment");
 }
